/** Rejects an AWAITING_APPROVAL execution (POST /api/v1/admin/executions/{id}/reject). */
export function rejectExecution(token: string, id: string): Promise<ExecutionInfo> {
  return adminRequest<ExecutionInfo>(token, `/api/v1/admin/executions/${encodeURIComponent(id)}/reject`, {
    method: 'POST',
  });
}

async function runExecutionAction(action: (t: string, id: string) => Promise<ExecutionInfo>, id: string) {
  setActionError(undefined);
  try {
    await action(token, id);
    setReloads((n) => n + 1);
  } catch (err) {
    if (err instanceof ApiError && err.status === 401) handleError(err);
    else setActionError(err instanceof Error ? err.message : 'Request failed');
  }
}
